-- One slot. Draft only.
BEGIN;
-- PT106-S3-Q5
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND q.stimulus=$batch01$Jane: Television programs and movies that depict violence among teenagers are extremely popular. Given how influential these media are, we have good reason to believe that these depictions cause young people to engage in violent behavior. Hence, depictions of violence among teenagers should be prohibited from movies and television programs, if only in those programs and movies promoted to young audiences.

Maurice: But you are recommending nothing short of censorship! Besides which, your claim that television and movie depictions of violence cause violence is mistaken: violence among young people predates movies and television by centuries.$batch01$ AND q.prompt=$batch01$Maurice's attempted refutation of Jane's argument is vulnerable to criticism on which one of the following grounds?$batch01$ AND q.correct_choice=$batch01$C$batch01$) THEN RAISE EXCEPTION 'Question changed: PT106-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$It presupposes that an unpopular policy cannot possibly achieve its intended purpose.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT106-S3-Q5 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$It confuses a subjective judgment of private moral permissibility with an objective description of social fact.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT106-S3-Q5 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$It rules out something as a cause of a current phenomenon solely on the ground that the phenomenon used to occur without that thing.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT106-S3-Q5 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$It cites purported historical facts that cannot possibly be verified.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT106-S3-Q5 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$It relies on an ambiguity in the term “violence” to justify a claim.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT106-S3-Q5 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT106-S3-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Jane's claim$batch01$, $batch01$Depictions of teenage violence cause some young people to act violently; she recommends a prohibition.$batch01$), (1, $batch01$Maurice's conclusion$batch01$, $batch01$Jane's causal claim is mistaken.$batch01$), (2, $batch01$Maurice's evidence$batch01$, $batch01$Youth violence existed centuries before movies and television.$batch01$), (3, $batch01$Evaluate$batch01$, $batch01$Can a newer factor cause *some* instances of an old phenomenon? Of course. Cars cause some injuries even though injuries existed before cars. The earlier existence of youth violence refutes the claim that media invented all youth violence, but Jane made no such claim. It does not refute a contributory cause today.$batch01$), (4, $batch01$Goal$batch01$, $batch01$Find the mistaken rejection of a current cause merely because the phenomenon predates it.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Maurice calls the proposed policy censorship, but his causal objection is not that an unpopular policy cannot work. Popularity never enters his evidence.$batch01$), ($batch01$B$batch01$, $batch01$The exchange is about a causal factual claim, not a confusion between private moral judgment and objective social fact.$batch01$), ($batch01$C$batch01$, $batch01$Youth violence existed without television and movies. That only shows those media are not required for *every* instance of youth violence. They might still contribute to violence now. Maurice rejects a possible cause because the effect once occurred without it.$batch01$), ($batch01$D$batch01$, $batch01$The historical claim may be verifiable. Even granting it fully, Maurice's inference remains flawed, so verifiability is not the criticism.$batch01$), ($batch01$E$batch01$, $batch01$“Violence” has the same basic meaning in Jane's present-day claim and Maurice's historical comparison. The error is about what that comparison proves.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT106-S3-Q5$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
